function matchSituations(userInput, ctx = {}) {
  const haystack = userInput.toLowerCase();
  const matched = [];
  for (const s of SITUATIONS) {
    const hits = [];
    if (s.trigger.keywords?.some((k) => haystack.includes(k.toLowerCase()))) {
      hits.push("keyword");
    }
    if (s.trigger.regex?.some((r) => new RegExp(r, "i").test(userInput))) {
      hits.push("regex");
    }
    if (s.trigger.contextMatch && matchesContext(s.trigger.contextMatch, ctx)) {
      hits.push("contextMatch");
    }
    if (hits.length > 0) matched.push({ situation: s, matchedOn: hits });
  }
  return matched;
}
function stackedMultiplier(matches) {
  return matches.reduce(
    (acc, m2) => acc * (m2.situation.adjust.multiplier ?? 1),
    1
  );
}
function stackedAddend(matches) {
  return matches.reduce((acc, m2) => acc + (m2.situation.adjust.addend ?? 0), 0);
}
function matchesContext(needle, haystack) {
  for (const k of Object.keys(needle)) {
    if (haystack[k] !== needle[k]) {
      return false;
    }
  }
  return true;
}

